 .pdm-logout-btn:hover { background: rgba(239,68,68,.1); color: #b91c1c; }

 /* Theme toggle icons */
 .t-sun { display: none; } .t-moon { display: block; }
 html.dark .t-sun { display: block; } html.dark .t-moon { display: none; }

