 /* Card header */
 .s-card-header {
 display: flex; align-items: center; justify-content: space-between;
 margin-bottom: 18px;
 }
 .s-card-title {
 font-family: var(--font-head); font-size: 15px; font-weight: 700;
 color: var(--text); letter-spacing: -.01em;
 }
