 .s-stat-pill {
 font-size: 10px; font-weight: 700; padding: 2px 8px;
 border-radius: 999px; margin-top: 5px; display: inline-block;
 }

 /* Status Badges */
 .s-badge {
 display: inline-flex; align-items: center; gap: 5px;
